"""Produce the calendar/accuracy inventory from the acquired, versioned circuit assets."""
import importlib.util,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('atlas_builder',ROOT/'scripts/build_circuit_atlas.py');module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
NAMES={'melbourne':('Albert Park','Australia'),'shanghai':('Shanghai International Circuit','China'),'suzuka':('Suzuka','Japan'),'miami':('Miami International Autodrome','United States'),'montreal':('Circuit Gilles-Villeneuve','Canada'),'monaco':('Circuit de Monaco','Monaco'),'barcelona':('Barcelona-Catalunya','Spain'),'spielberg':('Red Bull Ring','Austria'),'silverstone':('Silverstone','United Kingdom'),'spa':('Spa-Francorchamps','Belgium'),'hungaroring':('Hungaroring','Hungary'),'zandvoort':('Zandvoort','Netherlands'),'monza':('Monza','Italy'),'madrid':('Madring','Spain'),'baku':('Baku City Circuit','Azerbaijan'),'sepang':('Sepang · Bahrain GP in Malaysia','Malaysia'),'singapore':('Marina Bay','Singapore'),'austin':('Circuit of the Americas','United States'),'mexico':('Autodromo Hermanos Rodriguez','Mexico'),'interlagos':('Interlagos','Brazil'),'las-vegas':('Las Vegas Strip Circuit','United States'),'lusail':('Lusail','Qatar'),'yas-marina':('Yas Marina','United Arab Emirates')}
entries=[];rows=[];missing=[]
for round_no,v in enumerate(module.VENUES,1):
 ident,lat,lon,length,geo,date,theme,slug=v;p=module.DEST/(ident+'.json');data=json.loads(p.read_text()) if p.exists() else None
 warnings=data['warnings'] if data else ['Source acquisition pending; no synthetic substitute is provided']
 if not data:missing.append(ident)
 name,country=NAMES[ident]
 entries.append({'id':ident,'name':name,'country':country,'round':round_no,'raceDate':date,'referenceLength':length,'theme':theme,'status':'provisional' if warnings else 'source-derived','official':'https://www.formula1.com/en/racing/2026/'+slug,'file':ident+'.json','version':data['version'] if data else 'unavailable','warnings':warnings})
 rows.append(f'| {round_no} | {name} | {date} | {"OSM + SRTM proxy" if data else "PENDING"} | {data["length"] if data else "—"} / {length} m | {"; ".join(warnings) if warnings else "Mapped; not surveyed"} |')
manifest={'schema':'apex-calendar-2026-1','verifiedAt':'2026-11-11','sources':['https://www.formula1.com/en/racing/2026','https://www.fia.com/events/fia-formula-one-world-championship/season-2026/2026-fia-formula-one-world-championship'],'calendarChanges':['23 current rounds, not the original 24-round announcement.','Saudi Arabian April event canceled. Original April Bahrain event did not run at Sakhir.','Round 16 Bahrain Grand Prix in Malaysia uses Sepang, October 2–4.','Madring hosts the Spanish Grand Prix; Barcelona remains a separate round.'],'circuits':entries}
module.DEST.mkdir(parents=True,exist_ok=True);(module.DEST/'index.json').write_text(json.dumps(manifest,separators=(',',':')),encoding='utf8')
(ROOT/'docs/2026_CIRCUIT_INVENTORY.md').write_text('# 2026 circuit inventory\n\nVerified 11 November 2026 against the [current F1 calendar](https://www.formula1.com/en/racing/2026) and [FIA season calendar](https://www.fia.com/events/fia-formula-one-world-championship/season-2026/2026-fia-formula-one-world-championship). No current session telemetry was acquired.\n\n| Round | Circuit | Race date | Implemented asset | Mapped/reference length | Accuracy / outstanding review |\n| --- | --- | --- | --- | --- | --- |\n'+'\n'.join(rows)+'\n\nEach asset retains OSM way/structure IDs, acquisition date, licence, CRS, source precision limits, terrain sampling, EGM96 datum, estimated width and unavailable banking. A small length difference is a diagnostic, not proof of geometric accuracy.\n',encoding='utf8')
print(f'Calendar manifest: {len(entries)} venues; {len(missing)} missing: {missing}')
